package com.retailflow.pos.ledger;
import com.retailflow.pos.common.ApiResponse;import java.time.LocalDate;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/ledger") @PreAuthorize("hasRole('OWNER')") public class LedgerController{private final LedgerService s;public LedgerController(LedgerService s){this.s=s;}@GetMapping public ApiResponse<?>list(@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate from,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate to){return ApiResponse.ok(s.list(from,to));}@GetMapping("/summary")public ApiResponse<?>summary(){return ApiResponse.ok(s.summary());}}
